import { styled, Text } from '@tamagui/web';
import type { ReactNode } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { pickWebPressHandlers } from '../../helpers/pickAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { SpanActionAttributes } from '../../types/ElementAttributes';

export type MessageHighlightProps = SpanActionAttributes & {
	clickable?: boolean;
	variant?: 'critical' | 'relevant' | 'other' | 'link';
	children: ReactNode;
};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const messageHighlightFrame = {
	whiteSpace: 'nowrap',
	wordWrap: 'inherit',
	render: 'span',
	fontWeight: 500,
	borderRadius: {
		'focus-visible': '0.25rem',
	},
	outlineWidth: {
		'focus-visible': '1px',
	},
	outlineStyle: {
		'focus-visible': 'solid',
	},
	outlineColor: {
		'focus-visible': 'var(--rcx-color-stroke-highlight, #156ff5)',
	},
	boxShadow: {
		'focus-visible': '0 0 0 calc(1px + 2px) var(--rcx-color-stroke-extra-light-highlight, #d1ebfe)',
	},
} as const;

const messageHighlightTones = {
	critical: {
		color: 'var(--rcx-message-highlight-colors-critical-color, var(--rcx-color-status-font-on-danger, #9b1325))',
	},
	relevant: {
		color: 'var(--rcx-message-highlight-colors-relevant-color, var(--rcx-color-status-font-on-service-1, #974809))',
	},
	other: {
		color: 'var(--rcx-message-highlight-colors-other-color, var(--rcx-color-status-font-on-warning, #895f00))',
	},
	link: {
		color: 'var(--rcx-message-highlight-colors-link-color, var(--rcx-color-status-font-on-info, #095ad2))',
	},
} as const;

const messageHighlightClickable = {
	true: {
		cursor: 'pointer',
		textDecorationLine: {
			hover: 'underline',
		},
	},
} as const;

// end of generated

// Declared where it renders: zero-runtime only erases a `styled()` whose every use is in its own module
const MessageHighlightFrame = styled(Text, {
	...messageHighlightFrame,
	variants: { tone: messageHighlightTones, clickable: messageHighlightClickable },
});

function MessageHighlight(props: MessageHighlightProps) {
	const { variant = 'other', clickable, className, children } = props;
	const modifiers = [variant, clickable && 'clickable']
		.filter(Boolean)
		.map((modifier) => `rcx-message__highlight--${modifier}`)
		.join(' ');

	return (
		<MessageHighlightFrame
			tone={variant}
			clickable={!!clickable}
			className={prependClassName(className, `rcx-message__highlight ${modifiers}`)}
			render={
				<span
					{...ariaAndDataAttributes(props)}
					{...pickWebPressHandlers(props)}
					ref={props.ref}
					id={props.id}
					title={props.title}
					role={props.role}
					tabIndex={props.tabIndex}
				/>
			}
		>
			{children}
		</MessageHighlightFrame>
	);
}

export default MessageHighlight;
